"""Build versioned offline assets with no runtime CDN dependencies."""
from pathlib import Path
import hashlib,json,sys
ROOT=Path(__file__).resolve().parents[1];APP=ROOT/'APP'
def encoded(v):return (json.dumps(v,sort_keys=True,ensure_ascii=False,indent=2)+'\n').encode()
def sha(raw):return hashlib.sha256(raw).hexdigest()
def build():
    source_names=['compare.js','index.html','shell/app.js','shell/style.css','core/identity.js','core/catalog.js','core/legality.js','storage/db.js','storage/workspaces.js','build_pwa.py','build_portable.py']
    metadata={'version':'0.3.0-rebuilt','source_files':{'APP/'+p:sha((APP/p).read_bytes()) for p in source_names},'samples':{}}
    for seat,name,path in [('A','Jupitermon','DECKS/JUPITERMON.txt'),('B','Amaterasumon · Toho','DECKS/AMATERASUMON_TOHO.txt')]:
        metadata['samples'][seat]={'name':name,'text':(ROOT/path).read_text()};metadata['source_files'][path]=sha((ROOT/path).read_bytes())
    (APP/'app-data.json').write_bytes(encoded(metadata))
    assets=['index.html','app-data.json','compare.js','shell/app.js','shell/style.css','core/identity.js','core/catalog.js','core/legality.js','storage/db.js','storage/workspaces.js','manifest.webmanifest','icon.svg','icon-192.png','icon-512.png','catalog/manifest.json','catalog/restrictions.json','DeckCompare.html']
    manifest=json.loads((APP/'catalog/manifest.json').read_bytes());assets+=['catalog/'+c['path'] for c in manifest['chunks'].values()]
    files={p:sha((APP/p).read_bytes()) for p in sorted(assets)};version=sha(encoded(files))[:16]
    release={'schema':'digimon-static-release-v1','version':version,'assets':files};(APP/'release-manifest.json').write_bytes(encoded(release))
    source="""/* Generated by build_pwa.py. Installation is atomic; all catalog chunks are verified. */
'use strict';
const VERSION=__VERSION__,CACHE='digibattle-'+VERSION,FILES=__FILES__;
self.addEventListener('install',event=>event.waitUntil((async()=>{
 const cache=await caches.open(CACHE);
 try{const paths=Object.keys(FILES);for(let i=0;i<paths.length;i+=6)await Promise.all(paths.slice(i,i+6).map(async path=>{
  const url=new URL(path,self.registration.scope),r=await fetch(url,{cache:'reload'});if(!r.ok)throw Error('Offline asset unavailable: '+path);
  const raw=await r.clone().arrayBuffer(),digest=[...new Uint8Array(await crypto.subtle.digest('SHA-256',raw))].map(b=>b.toString(16).padStart(2,'0')).join('');
  if(digest!==FILES[path])throw Error('Offline integrity mismatch: '+path);await cache.put(url,r);
 }));}catch(error){await caches.delete(CACHE);throw error;}
})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const name of await caches.keys())if(name.startsWith('digibattle-')&&name!==CACHE)await caches.delete(name);await self.clients.claim();})()));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||url.origin!==self.location.origin||!url.href.startsWith(self.registration.scope))return;
 event.respondWith((async()=>{const cache=await caches.open(CACHE);const cached=await cache.match(event.request,{ignoreSearch:true});if(cached)return cached;try{return await fetch(event.request);}catch(error){if(event.request.mode==='navigate')return await cache.match(new URL('index.html',self.registration.scope));throw error;}})());
});
""".replace('__VERSION__',json.dumps(version)).replace('__FILES__',json.dumps(files,sort_keys=True))
    (APP/'service-worker.js').write_text(source,encoding='utf-8');print(f'Built PWA release {version}: {len(files)} verified offline assets')
if __name__=='__main__':build()
